/**
 * Modules generated by the `notesData()` plugin in vite.config.ts from
 * src/data/notes.ts. See src/data/notes-index.ts, their only importer.
 */
declare module 'virtual:notes-meta' {
  import type { Note } from '@/data/notes'
  export const notes: Omit<Note, 'body'>[]
}

declare module 'virtual:notes-bodies' {
  export const bodies: Record<string, (() => Promise<{ default: string }>) | undefined>
}
